  public void Log(string text){if(IsDisposed)return;if(InvokeRequired){try{BeginInvoke((Action)(()=>Log(text)));}catch{}return;}log.AppendText(DateTime.Now.ToString("HH:mm:ss")+"  "+text+Environment.NewLine);}
  async void Work(Action action){if(busy){Log("An operation is already running.");return;}busy=true;foreach(var b in actions)if(!b.IsDisposed)b.Enabled=false;try{await Task.Run(action);}catch(Exception e){Log("ERROR: "+e.Message);MessageBox.Show(this,e.Message,"Overdrive",MessageBoxButtons.OK,MessageBoxIcon.Information);}finally{busy=false;foreach(var b in actions)if(!b.IsDisposed)b.Enabled=true;TickStatus();}}
