  void TickStatus(){try{var memory=Native.ReadMemory();double total=memory.total/1073741824.0,available=memory.available/1073741824.0;var drive=new DriveInfo(Path.GetPathRoot(Environment.SystemDirectory));cpuLoad=Adaptive.Cpu();var plan=Adaptive.Plan(available/total,drive.AvailableFreeSpace/(double)drive.TotalSize,drive.AvailableFreeSpace/1073741824.0,cpuLoad);adaptivePage=plan[2];if(adaptiveTitle!=null&&!adaptiveTitle.IsDisposed){adaptiveTitle.Text=plan[0];adaptiveText.Text=plan[1];}stats.Text="CPU "+(double.IsNaN(cpuLoad)?"—":cpuLoad.ToString("N0")+"%")+"  •  "+string.Format("{0:N1} / {1:N1} GB RAM in use     •     {2:N1} GB system-drive space     •     {3}\r\nNo telemetry. No startup agent. Changes are explicit and logged.",total-available,total,drive.AvailableFreeSpace/1073741824.0,Store.Admin?"ADMINISTRATOR":"STANDARD USER");if(sessionPath!=null&&File.Exists(sessionPath)){var d=Store.Load<FocusSession>(sessionPath);if(sessionLabel!=null&&!sessionLabel.IsDisposed)sessionLabel.Text="Session: "+d.State+"   ·   "+d.Closed.Count+" processes closed";if(d.State=="Restored")sessionPath=null;}}catch{}}
