  void ProfilesPage(){var p=Page("Choose the tradeoff.","Review every registry setting before applying. Responsive keeps gaming preferences unchanged. Gaming adds capture and Game Mode settings. Aggressive also removes visual polish and optional background features.");profile=new ComboBox{Width=300,DropDownStyle=ComboBoxStyle.DropDownList};profile.Items.AddRange(new object[]{"Responsive","Gaming","Aggressive"});profile.SelectedIndex=1;p.Controls.Add(profile);profileGrid=Grid(300);profileGrid.Columns.Add("group","Area");profileGrid.Columns.Add("name","Setting");profileGrid.Columns.Add("effect","Purpose");profileGrid.Columns.Add("tradeoff","Tradeoff");p.Controls.Add(profileGrid);Action refresh=()=>{string mode=profile.Text;profileGrid.Rows.Clear();foreach(var t in Profiles.All.Where(t=>(mode=="Aggressive"||!t.Aggressive)&&(mode!="Responsive"||t.Group!="Gaming")))profileGrid.Rows.Add(t.Group,t.Name,t.Effect,t.Tradeoff);foreach(string n in Native.MotionNames.Take(mode=="Aggressive"?Native.Actions.Length:10))profileGrid.Rows.Add("Motion",n,"Disable through Windows API",n=="Font smoothing"?"Jagged text":"No visual transition");};profile.SelectedIndexChanged+=(s,e)=>refresh();refresh();p.Controls.Add(Button("Apply reviewed profile",()=>{string choice=profile.Text;if(!Store.Admin){Log("Use Run as administrator for a complete profile. No changes applied.");return;}Work(()=>Profiles.Apply(choice,Log));}));p.Controls.Add(LabelText("Original values are saved before writes. Recovery preserves newer settings that changed after a backup. Some policies are unsupported on Windows Home. Reopen Performance Options to refresh an already-open dialog.",70));}
  void FocusPage(){var p=Page("Give one app the headroom.","Select a running game, then explicitly choose optional background apps to close. Power and optional priority changes restore automatically when the target exits. Closed apps must be reopened manually.");game=new ComboBox{Width=650,DropDownStyle=ComboBoxStyle.DropDownList};p.Controls.Add(Row(game,Button("Refresh apps",()=>RefreshProcesses(),false)));candidates=Checks(235);p.Controls.Add(candidates);var force=new CheckBox{Text="Force-close selected apps if needed — unsaved work can be lost",Width=850,Height=34};var priority=new CheckBox{Text="Try Above Normal game priority (test this per game)",Width=850,Height=32};p.Controls.Add(force);p.Controls.Add(priority);p.Controls.Add(Row(Button("Select listed candidates",()=>{for(int i=0;i<candidates.Items.Count;i++)candidates.SetItemChecked(i,true);},false),Button("Clear selection",()=>{for(int i=0;i<candidates.Items.Count;i++)candidates.SetItemChecked(i,false);},false)));p.Controls.Add(Row(Button("Start focus session",()=>{var target=game.SelectedItem as AppProcess;var picked=candidates.CheckedItems.Cast<AppProcess>().ToList();bool hard=force.Checked,raise=priority.Checked;Work(()=>{sessionPath=Overdrive.Focus.Begin(target,picked,hard,raise,Log);});}),Button("Restore session",()=>Work(()=>{string file=sessionPath??Path.Combine(Store.Root,"active-session.json");Overdrive.Focus.Restore(file,Log);})))) ;sessionLabel=LabelText("No focus session active.",38);p.Controls.Add(sessionLabel);game.SelectedIndexChanged+=(s,e)=>RefreshCandidates();RefreshProcesses();}
  void RefreshProcesses(){Work(()=>{var list=Overdrive.Focus.Snapshot();UI(()=>{processes=list;game.Items.Clear();foreach(var x in list.Where(x=>!string.IsNullOrEmpty(x.Title)&&x.Pid!=Process.GetCurrentProcess().Id).OrderBy(x=>x.Name))game.Items.Add(x);if(game.Items.Count>0)game.SelectedIndex=0;RefreshCandidates();});});}
  void RefreshCandidates(){if(candidates==null)return;candidates.Items.Clear();var selected=game.SelectedItem as AppProcess;if(selected==null)return;var tree=Overdrive.Focus.ProtectedTree(processes,selected.Pid);foreach(var p in processes.Where(x=>Overdrive.Focus.CanClose(x,tree,Process.GetCurrentProcess().SessionId,Store.Sid)).OrderByDescending(x=>x.Memory))candidates.Items.Add(p,false);}
  void DebloatPage(){var p=Page("Remove optional packages.","Current-user removal only. The allowlist excludes Windows Store, WebView, Xbox identity, Gaming Services, security, drivers and application frameworks.");optional=Checks(300);p.Controls.Add(optional);p.Controls.Add(Button("Load installed optional apps",()=>Work(()=>{var apps=Debloat.Installed();UI(()=>{optional.Items.Clear();foreach(var a in apps)optional.Items.Add(a,false);});Log(apps.Count+" removable optional apps found.");})));var acknowledge=new CheckBox{Text="I understand removing an app can delete its settings/data; reinstall is through Microsoft Store.",Width=890,Height=44};p.Controls.Add(acknowledge);p.Controls.Add(Button("Remove selected apps",()=>{if(!acknowledge.Checked){Log("Read and acknowledge the app-data tradeoff first.");return;}var apps=optional.CheckedItems.Cast<OptionalApp>().ToList();if(apps.Count==0){Log("Select at least one optional app.");return;}Work(()=>{Debloat.Remove(apps,Log);});}));}
  void StartupPage(){var p=Page("Start with less.","Disable selected current-user Run entries. This does not close running apps. Remote access, security, audio and input helpers are protected. Other startup locations are listed in the project limitations.");startups=Checks(300);p.Controls.Add(startups);Action refresh=()=>{startups.Items.Clear();foreach(string key in Profiles.Startup().Keys)startups.Items.Add(key,false);};refresh();p.Controls.Add(Row(Button("Refresh startup entries",refresh,false),Button("Disable selected entries",()=>{var names=startups.CheckedItems.Cast<string>().ToList();Work(()=>{var tx=new Transaction("Selected startup entries",Log);foreach(string n in names)tx.RemoveStartup(n);tx.Finish();UI(refresh);});})));}
  void CleanupPage(){var p=Page("Preview. Then delete.","Only files older than seven days in Windows/user temporary folders. Documents, downloads, browser profiles, game shaders and installer caches are outside this cleanup.");cleanSummary=LabelText("No scan yet.",38);p.Controls.Add(cleanSummary);cleanGrid=Grid(280);cleanGrid.Columns.Add("file","Temporary file");cleanGrid.Columns.Add("mb","MB");p.Controls.Add(cleanGrid);p.Controls.Add(Row(Button("Scan old temporary files",()=>Work(()=>{var found=Cleaner.Scan(Cleaner.Roots());UI(()=>{tempFiles=found;cleanGrid.Rows.Clear();foreach(var f in found.Take(3000))cleanGrid.Rows.Add(f.Path,(f.Bytes/1048576.0).ToString("N2"));cleanSummary.Text=found.Count.ToString("N0")+" files / "+(found.Sum(x=>x.Bytes)/1048576.0).ToString("N1")+" MB. Showing up to 3,000 paths.";});})),Button("Delete previewed files",()=>{var files=tempFiles.ToList();if(files.Count==0){Log("Scan first; nothing selected for deletion.");return;}Work(()=>{Cleaner.Delete(files,Log);UI(()=>{tempFiles.Clear();cleanGrid.Rows.Clear();cleanSummary.Text="Cleanup complete. Run another scan to verify remaining files.";});});})));p.Controls.Add(LabelText("Deletion is permanent. Changed or locked files and reparse points are skipped. Cleanup frees disk space; it is not an FPS benchmark.",55));}
  void BenchmarkPage(){var p=Page("Prove the result.","Import two single-process PresentMon captures from the same game, scene and settings. Warm up first. Repeat each run several times; record losses as honestly as gains.");baseLabel=LabelText(baseline==null?"BASELINE — no capture":baseline.ToString(),55);tunedLabel=LabelText(tuned==null?"TUNED — no capture":tuned.ToString(),55);p.Controls.Add(baseLabel);p.Controls.Add(tunedLabel);compare=LabelText(Benchmarks.Compare(baseline,tuned),110);p.Controls.Add(compare);p.Controls.Add(Row(Button("Import baseline CSV",()=>ImportCapture(false)),Button("Import tuned CSV",()=>ImportCapture(true))));p.Controls.Add(Button("Export comparison JSON",()=>{if(baseline==null||tuned==null){Log("Import both captures first.");return;}using(var dialog=new SaveFileDialog{Filter="JSON report|*.json",FileName="Overdrive-comparison.json"})if(dialog.ShowDialog(this)==DialogResult.OK)Store.Save(dialog.FileName,new {Baseline=baseline,Tuned=tuned,Interpretation=Benchmarks.Compare(baseline,tuned),Method="Average FPS=1000/mean interval; 1% low=1000/mean slowest 1%; p99 nearest-rank interval"});}));p.Controls.Add(LabelText("Supported columns: MsBetweenPresents, CPUFrameTime or FrameTimeMs. This build imports captures; it does not bundle PresentMon or include a live FPS overlay. Use the same column and capture configuration for both runs.",80));}
  void ImportCapture(bool optimized){using(var dialog=new OpenFileDialog{Filter="Frame-time CSV|*.csv"})if(dialog.ShowDialog(this)==DialogResult.OK){string file=dialog.FileName;Work(()=>{var result=Benchmarks.Import(file);UI(()=>{if(optimized){tuned=result;tunedLabel.Text=result.ToString();}else{baseline=result;baseLabel.Text=result.ToString();}compare.Text=Benchmarks.Compare(baseline,tuned);});});}}
  class BackupItem {public string Path,Text;public override string ToString(){return Text;}}
  void RecoveryPage(){var p=Page("Make changes reversible.","Restore original values from a profile journal on this PC and user. Restore the newest profile first. Changes made outside Overdrive after a backup are preserved and reported as conflicts.");history=new ListBox{Width=890,Height=270,BackColor=panel,ForeColor=Color.White};p.Controls.Add(history);Action refresh=()=>{history.Items.Clear();foreach(string file in Directory.GetFiles(Store.History,"*.json").Where(f=>!f.EndsWith(".receipt.json")).OrderByDescending(f=>f)){try{var j=Store.Load<Journal>(file);if(j.Changes!=null)history.Items.Add(new BackupItem{Path=file,Text=j.Created+"   "+j.Label+"   ["+j.State+"]"});}catch{}}};refresh();p.Controls.Add(Row(Button("Restore selected backup",()=>{var item=history.SelectedItem as BackupItem;if(item==null){Log("Choose a backup first.");return;}Work(()=>{Transaction.Restore(item.Path,Log);UI(refresh);});}),Button("Recover focus session",()=>Work(()=>Overdrive.Focus.Restore(Path.Combine(Store.Root,"active-session.json"),Log)))));p.Controls.Add(Row(Button("Refresh backups",refresh,false),Button("Open local data folder",()=>Process.Start("explorer.exe","\""+Store.Root+"\""),false)));p.Controls.Add(LabelText("App removal and deleted temporary files are not reversible through a registry journal. Focus recovery restores power and priority; it cannot recover unsaved work from closed apps.",70));}
  public void Render(string path,string page){Show();Application.DoEvents();ShowPage(page);Application.DoEvents();using(var bitmap=new Bitmap(Width,Height)){DrawToBitmap(bitmap,new Rectangle(Point.Empty,Size));using(var footer=new Bitmap(log.Parent.Width,log.Parent.Height)){log.Parent.DrawToBitmap(footer,new Rectangle(Point.Empty,footer.Size));using(var graphics=Graphics.FromImage(bitmap)){var screen=log.Parent.PointToScreen(Point.Empty);graphics.DrawImageUnscaled(footer,screen.X-Left,screen.Y-Top);}}bitmap.Save(path,System.Drawing.Imaging.ImageFormat.Png);Store.Save(path+".layout.json",new {Page=pageHost.Bounds,Flow=pageHost.Controls.Count>0?pageHost.Controls[0].Bounds:Rectangle.Empty,Log=log.Bounds,Rows=((TableLayoutPanel)pageHost.Parent).GetRowHeights()});}Close();}
