 static class Program {
  [STAThread]static int Main(string[] args){try{if(args.Length>0&&args[0]=="--test-worker"){System.Threading.Thread.Sleep(60000);return 0;}if(args.Length>0&&args[0]=="--self-test"){string result=Tests.Run();if(args.Length>1)File.WriteAllText(args[1],result);else Console.WriteLine(result);return 0;}if(args.Length>1&&args[0]=="--watch-session"){Overdrive.Focus.Watch(args[1]);return 0;}if(args.Length>0&&args[0]=="--audit-apps"){string json=Store.Json().Serialize(Debloat.Installed());if(args.Length>1)File.WriteAllText(args[1],json);return 0;}if(args.Length>1&&args[0]=="--export-config"){Directory.CreateDirectory(args[1]);Store.Save(Path.Combine(args[1],"Electric-Gaze.json"),GazeSettings.Default());Store.Save(Path.Combine(args[1],"tweaks.json"),Profiles.All);return 0;}Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);using(var form=new SimpleForm(args.Length>0&&args[0]=="--optimize")){if(args.Length>1&&args[0]=="--smoke-ui")form.Smoke(args[1]);else if(args.Length>1&&args[0]=="--render")form.Render(args[1]);else Application.Run(form);}return 0;}catch(Exception e){string error=e.ToString();if(args.Length>1)try{File.WriteAllText(args[1]+".error.txt",error);}catch{}else MessageBox.Show(error,"Overdrive error");return 1;}}
 }
